const http = require('node:http');
const packages = {
  'is-number': {
    '7.0.0': {
      name: 'is-number',
      version: '7.0.0',
      dist: { tarball: 'https://registry.npmjs.org/is-number/-/is-number-7.0.0.tgz' }
    }
  }
};

const server = http.createServer((req, res) => {
  const match = req.url.match(/^\/([^/@][^/]*?)(?:\/(.+))?$/);
  if (match) {
    const pkg = match[1];
    const version = match[2];
    if (packages[pkg]) {
      res.writeHead(200, { 'content-type': 'application/json' });
      if (version) {
        res.end(JSON.stringify(packages[pkg][version] || {}));
      } else {
        res.end(JSON.stringify({ versions: packages[pkg] }));
      }
      return;
    }
  }
  res.writeHead(404);
  res.end('not found');
});

server.listen(4873, '127.0.0.1', () => {
  console.log('Registry listening on http://127.0.0.1:4873');
});

setTimeout(() => process.exit(0), 120000);

